    vector<int> first_child;
    vector<int> next_sibling;
    vector<int> prev_sibling;
    vector<int> subtree;     // subtree size
    vector<double> flow;     // flow on arc (v, parent[v]); sign: positive means flow from v toward parent? 
    // We'll store flow_to_parent: amount of flow sent from node v to parent[v] along the tree edge.
    // For a source->target edge, flow is nonnegative in the source->target direction. We store
    // the directed flow separately via edge orientation.
    vector<int> arc_src;     // for tree edge of node v (v!=root): the source endpoint index (0..n-1) or -1 if artificial
    vector<int> arc_tgt;     // target endpoint (0..m-1) or -1 if artificial
    vector<double> potential;

    int root;

    double cost(int i, int j) const { return M[i*(int64_t)m + j]; }

    void build_initial() {
        N = n + m + 1;
        root = n + m;
        parent.assign(N, root);
        depth.assign(N, 1);
        first_child.assign(N, -1);
        next_sibling.assign(N, -1);
        prev_sibling.assign(N, -1);
        subtree.assign(N, 1);
        flow.assign(N, 0.0);
        arc_src.assign(N, -1);
        arc_tgt.assign(N, -1);
        potential.assign(N, 0.0);

        // root children: all sources and targets, linked list
        // link in order sources then targets
        auto link_child = [&](int p, int c) {
            parent[c] = p;
            prev_sibling[c] = -1;
            next_sibling[c] = first_child[p];
            if (first_child[p] != -1) prev_sibling[first_child[p]] = c;
            first_child[p] = c;
