            int v = st.back(); st.pop_back();
            order.push_back(v);
            for (int c = first_child[v]; c != -1; c = next_sibling[c]) st.push_back(c);
        }
        for (int k = (int)order.size()-1; k >= 0; --k) {
            int v = order[k];
            int s = 1;
            for (int c = first_child[v]; c != -1; c = next_sibling[c]) s += subtree[c];
            subtree[v] = s;
        }
    }

    // Find entering arc: most negative reduced cost among all source-target arcs.
    // rc(i,j) = M[i,j] - potential[i] + potential[j]
    // Also consider? Artificial arcs are tree or not. Non-tree artificial arcs: initially all
    // artificial are tree. After pivots some artificial leave the tree and could re-enter.
    // We must allow non-tree artificial arcs to enter too, otherwise we can get stuck.
    // Artificial arcs: source i -> root, cost BIG, rc = BIG - pot[i] + pot[root]
    //                  root -> target j, cost BIG, rc = BIG - pot[root] + pot[j]
    // These are non-tree only if the node is not directly connected to root.
    bool find_entering(int& ei, int& ej, double& best_rc) {
        best_rc = -1e-12;
        ei = ej = -1;
        // real arcs
        for (int i = 0; i < n; ++i) {
            double pi = potential[i];
            const double* row = M + i*(int64_t)m;
            for (int j = 0; j < m; ++j) {
                double rc = row[j] - pi + potential[n + j];
                if (rc < best_rc) { best_rc = rc; ei = i; ej = j; }
            }
        }
        // artificial arcs that are not currently tree edges
