            if (parent[i] == root && arc_src[i] == -1) continue; // already tree (artificial)
            double rc = big - potential[i] + potential[root];
            if (rc < best_rc) { best_rc = rc; ei = i; ej = -1; } // -1 marks artificial source->root
        }
        for (int j = 0; j < m; ++j) {
            if (parent[n+j] == root && arc_src[n+j] == -1) continue;
            double rc = big - potential[root] + potential[n+j];
            if (rc < best_rc) { best_rc = rc; ei = -1; ej = j; } // artificial root->target
        }
        return ei != -1 || ej != -1;
    }

    // pivot
    bool pivot(int ei, int ej) {
        // entering arc: from u to v
        int u, v;
        bool entering_artificial = false;
        if (ei >= 0 && ej >= 0) { u = ei; v = n + ej; }
        else if (ei >= 0 && ej < 0) { u = ei; v = root; entering_artificial = true; }
