// Transportation network simplex (complete bipartite), rooted at an artificial root.
// Initial basis: all nodes connected to root by artificial arcs of cost BIG.
// Pivot rule: Dantzig (most negative reduced cost), Bland-ish tie break by (i,j).
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <chrono>
#include <random>
#include <cstring>
using namespace std;

struct NS {
    int n, m, N, root;
    const double* M;
    double BIG;

    vector<int> parent, depth, head_child, next_sib, prev_sib, sub;
    // tree arc associated with node v (connects v and parent[v]):
    //   tsrc[v], ttgt[v]: endpoints in source/target index, or -1 if artificial
    //   tdir[v]: +1 if natural arc direction is v -> parent, -1 if parent -> v
    //   flow[v]: nonnegative flow in the natural arc direction
    vector<int> tsrc, ttgt, tdir;
    vector<double> flow, pot;

    explicit NS(int n_, int m_): n(n_), m(m_) {
        N = n + m + 1; root = n + m;
        parent.resize(N); depth.resize(N); head_child.resize(N);
        next_sib.resize(N); prev_sib.resize(N); sub.resize(N);
        tsrc.resize(N); ttgt.resize(N); tdir.resize(N);
        flow.resize(N); pot.resize(N);
    }

    inline double cost_at(int i, int j) const { return M[(int64_t)i*m + j]; }

    void link_child(int p, int c) {
        parent[c] = p;
        prev_sib[c] = -1;
        next_sib[c] = head_child[p];
        if (head_child[p] != -1) prev_sib[head_child[p]] = c;
        head_child[p] = c;
    }
    void unlink(int v) {
        int p = parent[v];
        int a = prev_sib[v], b = next_sib[v];
        if (a != -1) next_sib[a] = b; else head_child[p] = b;
        if (b != -1) prev_sib[b] = a;
        next_sib[v] = prev_sib[v] = -1;
    }

    void init(const double* a, const double* b, const double* M_) {
        M = M_;
        BIG = 0;
        for (int64_t k = 0, nm = (int64_t)n*m; k < nm; ++k) if (M[k] > BIG) BIG = M[k];
        BIG += 1.0;

        fill(head_child.begin(), head_child.end(), -1);
        fill(next_sib.begin(), next_sib.end(), -1);
        fill(prev_sib.begin(), prev_sib.end(), -1);
        parent[root] = -1; depth[root] = 0; pot[root] = 0;
        // children of root: all sources then targets (link in reverse so order is increasing)
        for (int i = n-1; i >= 0; --i) {
            link_child(root, i);
            depth[i] = 1;
            tsrc[i] = -1; ttgt[i] = -1; tdir[i] = +1; // natural dir: source -> root
            flow[i] = a[i];
            pot[i] = BIG; // rc = BIG - pot[i] + pot[root] = 0
        }
        for (int j = m-1; j >= 0; --j) {
            int v = n + j;
            link_child(root, v);
            depth[v] = 1;
            tsrc[v] = -1; ttgt[v] = -1; tdir[v] = -1; // natural dir: root -> target
            flow[v] = b[j];
            pot[v] = -BIG;
        }
        recompute_sub();
    }

    void recompute_sub() {
        // iterative postorder
        vector<int> order; order.reserve(N);
        vector<int> st = {root};
        while (!st.empty()) {
            int v = st.back(); st.pop_back();
            order.push_back(v);
            for (int c = head_child[v]; c != -1; c = next_sib[c]) st.push_back(c);
        }
        for (int k = (int)order.size()-1; k >= 0; --k) {
            int v = order[k];
            int s = 1;
            for (int c = head_child[v]; c != -1; c = next_sib[c]) s += sub[c];
            sub[v] = s;
        }
    }

    // entering arc: returns true and sets kind.
    // kind 0: real arc ei->ej (source ei to target ej)
    // kind 1: artificial source ei -> root
    // kind 2: artificial root -> target ej
    bool find_entering(int& ei, int& ej, int& kind, double& rc_out) {
        double best = -1e-9;
        ei = ej = -1; kind = -1;
        for (int i = 0; i < n; ++i) {
            double pi = pot[i];
            const double* row = M + (int64_t)i*m;
            for (int j = 0; j < m; ++j) {
                double rc = row[j] - pi + pot[n+j];
                if (rc < best) { best = rc; ei = i; ej = j; kind = 0; }
            }
        }
        for (int i = 0; i < n; ++i) {
            bool in_tree = (parent[i] == root && tsrc[i] == -1);
            if (in_tree) continue;
            double rc = BIG - pot[i] + pot[root];
            if (rc < best) { best = rc; ei = i; ej = -1; kind = 1; }
        }
        for (int j = 0; j < m; ++j) {
            int v = n+j;
            bool in_tree = (parent[v] == root && tsrc[v] == -1);
            if (in_tree) continue;
            double rc = BIG - pot[root] + pot[v];
            if (rc < best) { best = rc; ei = -1; ej = j; kind = 2; }
        }
        rc_out = best;
        return kind != -1;
    }

    // Is tree arc of node v the same as entering arc? (degenerate, skip)
    bool same_arc(int v, int ei, int ej, int kind) const {
        if (kind == 0) return tsrc[v] == ei && ttgt[v] == ej;
        return false;
    }

    struct Leave { int node; double delta; bool found; };

    // Determine leaving arc and delta.
    // Entering flow is added in natural direction of entering arc.
    // u = tail (flow leaves u), w = head (flow arrives at w).
    Leave find_leaving(int u, int w, int ei, int ej, int kind) {
        // mark ancestors of u
        vector<int> anc(N, 0);
        for (int x = u; x != -1; x = parent[x]) anc[x] = 1;
        int lca = w;
        while (lca != -1 && !anc[lca]) lca = parent[lca];

        // Walk u up to lca: adding flow toward lca.
        // The tree arc at node x (x on path, x != lca) connects x to parent.
        // We are pushing additional flow from x toward parent (i.e. from subtree up).
        // If tdir[x] == +1 (natural dir x -> parent), residual allows increase: no block.
        // If tdir[x] == -1 (natural dir parent -> x), we decrease flow[x]; blocks at flow[x].
        // Walk w up to lca: pushing flow from parent toward w (down the path).
        // If tdir[x] == -1 (natural parent -> x), flow increases: no block.
        // If tdir[x] == +1 (natural x -> parent), flow decreases: blocks at flow[x].
        double delta = numeric_limits<double>::infinity();
        int leave = -1;
        // candidate comparison: smallest delta, tie break by smaller node index (Bland-ish)
        auto consider = [&](int x, double cap) {
            if (cap < delta - 1e-15 || (fabs(cap - delta) <= 1e-15 && (leave < 0 || x < leave))) {
                delta = cap; leave = x;
            }
        };
        for (int x = u; x != lca; x = parent[x]) {
            if (tdir[x] == -1) consider(x, flow[x]);
        }
        for (int x = w; x != lca; x = parent[x]) {
            if (tdir[x] == +1) consider(x, flow[x]);
        }
        if (leave < 0) {
            // unbounded — should not happen with artificial arcs present in formulation
            delta = 0;
        }
        return {leave, delta, leave >= 0};
    }

    void update_flows(int u, int w, int leave, double delta) {
        vector<int> anc(N, 0);
        for (int x = u; x != -1; x = parent[x]) anc[x] = 1;
        int lca = w;
        while (lca != -1 && !anc[lca]) lca = parent[lca];
        for (int x = u; x != lca; x = parent[x]) {
            if (tdir[x] == +1) flow[x] += delta;
            else flow[x] -= delta;
        }
        for (int x = w; x != lca; x = parent[x]) {
            if (tdir[x] == -1) flow[x] += delta;
            else flow[x] -= delta;
        }
        if (leave >= 0) flow[leave] = 0;
    }

    // Rehang the tree so that `leave` arc is removed and entering arc u->w is added.
    // The subtree that was on the leave side gets reattached.
    void rehang(int u, int w, int leave, int ei, int ej, int kind) {
        // The leaving arc connects `leave` to parent[leave]. Removing it splits tree
        // into component S = subtree(leave) and the rest.
        // Entering arc connects u and w; exactly one of them is in S.
        // We reroot S at the endpoint that is in S and attach it under the other endpoint.
        bool u_in_S = false;
        for (int x = u; x != -1; x = parent[x]) if (x == leave) { u_in_S = true; break; }

        int in_S = u_in_S ? u : w;
        int out_S = u_in_S ? w : u;

        // Collect the path from in_S up to leave (inclusive): these nodes reverse parent links.
        vector<int> path;
        for (int x = in_S; ; x = parent[x]) { path.push_back(x); if (x == leave) break; }

        // Detach leave from its parent
        unlink(leave);

        // Reverse edges along path.
        // Before: path[0]=in_S, path.back()=leave, parent[path[k]] = path[k+1] (except last).
        // After: parent[path[k+1]] = path[k], and in_S becomes child of out_S.
        // For each reversed edge, the arc data (tsrc, ttgt, tdir, flow) stays with the node
        // that currently stores it. After reversal the node storing the arc changes:
        // currently arc of edge (path[k], path[k+1]) is stored at path[k] (the child).
        // After reversal child is path[k+1], so arc data moves to path[k+1], and tdir flips.
        // We process from the top.
        // Save arc data per edge before moving.
        struct Arc { int tsrc, ttgt, tdir; double flow; };
        vector<Arc> arcs(path.size());
        for (size_t k = 0; k+1 < path.size(); ++k) {
            int child = path[k];
            arcs[k] = {tsrc[child], ttgt[child], tdir[child], flow[child]};
        }
        // also the entering arc will be stored at in_S (path[0]) connecting to out_S
        // First, re-parent along reversed path: for k from 0..len-2:
        //   new child = path[k+1], new parent = path[k]
        //   unlink path[k+1] from its current parent (which is path[k+2] or, for the
        //   top, already unlinked). Careful: path[k] for k>=1 is still linked to its
        //   parent path[k+1]. We must unlink path[k] before linking path[k+1] under it? 
        //   Let's detach all path nodes except leave (already detached) from their parents,
        //   then relink.
        for (size_t k = 0; k+1 < path.size(); ++k) unlink(path[k]);
        // now all path nodes are detached (their own children lists still intact, minus
        // the child that was the previous path node — which we unlinked).
        // Relink: path[k+1] becomes child of path[k], arc data from arcs[k] moved, tdir flipped.
        for (size_t k = 0; k+1 < path.size(); ++k) {
            int neu_parent = path[k];
            int neu_child = path[k+1];
            link_child(neu_parent, neu_child);
            tsrc[neu_child] = arcs[k].tsrc;
            ttgt[neu_child] = arcs[k].ttgt;
            tdir[neu_child] = -arcs[k].tdir;
            flow[neu_child] = arcs[k].flow;
        }
        // attach in_S under out_S with the entering arc
        link_child(out_S, in_S);
        if (kind == 0) { tsrc[in_S] = ei; ttgt[in_S] = ej; }
        else { tsrc[in_S] = -1; ttgt[in_S] = -1; }
        // natural direction of entering arc is u -> w.
        // in_S is the child, out_S is parent.
        // tdir = +1 if natural dir is child -> parent, i.e. in_S == u.
        tdir[in_S] = (in_S == u) ? +1 : -1;
        flow[in_S] = 0; // set by caller after delta known — we'll set flow outside
        // fix depths in the reattached subtree (subtree of out_S's new child in_S, which
        // now contains all of old S). Depth of in_S = depth[out_S] + 1, then BFS.
        vector<int> st = {in_S};
        depth[in_S] = depth[out_S] + 1;
        while (!st.empty()) {
            int v = st.back(); st.pop_back();
            for (int c = head_child[v]; c != -1; c = next_sib[c]) {
                depth[c] = depth[v] + 1;
                st.push_back(c);
            }
        }
        recompute_sub();
    }

    void update_potentials_full() {
        // recompute potentials from scratch consistent with tree arcs
        pot[root] = 0;
        vector<int> st = {root};
        while (!st.empty()) {
            int v = st.back(); st.pop_back();
            for (int c = head_child[v]; c != -1; c = next_sib[c]) {
                // rc of tree arc = 0.
                // natural arc: if real, cost = M[tsrc, ttgt]; if artificial, cost = BIG.
                double c_cost;
                if (tsrc[c] == -1) c_cost = BIG;
                else c_cost = cost_at(tsrc[c], ttgt[c]);
                // natural direction: tdir +1 means child -> parent, so the arc goes from
                // child to parent. rc = cost - pot[child] + pot[parent] = 0
                // => pot[child] = pot[parent] + cost.
                // tdir -1 means parent -> child: rc = cost - pot[parent] + pot[child] = 0
                // => pot[child] = pot[parent] - cost.
                if (tdir[c] == +1) pot[c] = pot[v] + c_cost;
                else pot[c] = pot[v] - c_cost;
                st.push_back(c);
            }
        }
    }

    int solve(const double* a, const double* b, const double* M_, double* G, int max_iter) {
        init(a, b, M_);
        int it;
        for (it = 0; it < max_iter; ++it) {
            int ei, ej, kind; double rc;
            if (!find_entering(ei, ej, kind, rc)) break;
            int u, w;
            if (kind == 0) { u = ei; w = n + ej; }
            else if (kind == 1) { u = ei; w = root; }
            else { u = root; w = n + ej; }
            auto L = find_leaving(u, w, ei, ej, kind);
            if (!L.found) { fprintf(stderr, "unbounded\n"); break; }
            update_flows(u, w, L.node, L.delta);
            rehang(u, w, L.node, ei, ej, kind);
            // set flow on new tree arc (stored at the child endpoint = the one in S)
            // after rehang, the entering arc's flow is stored at whichever of u,w is child.
            // find it:
            int child_end = (parent[u] == w) ? u : w;
            flow[child_end] = L.delta;
            update_potentials_full();
        }
        // extract plan: tree arcs that are real
        memset(G, 0, sizeof(double)*(size_t)n*(size_t)m);
        for (int v = 0; v < N; ++v) {
            if (v == root) continue;
            if (tsrc[v] >= 0) G[(int64_t)tsrc[v]*m + ttgt[v]] = flow[v];
        }
        return it;
    }
};

int main() {
    int n = 60;
    mt19937 rng(1);
    uniform_real_distribution<double> U(0,1);
    vector<double> sp(n*2), tp(n*2);
    for (auto& x: sp) x = U(rng);
    for (auto& x: tp) x = U(rng);
    vector<double> M(n*(int64_t)n);
    for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) {
        double dx = sp[2*i]-tp[2*j], dy = sp[2*i+1]-tp[2*j+1];
        M[i*(int64_t)n + j] = sqrt(dx*dx+dy*dy);
    }
    vector<double> a(n, 1.0/n), b(n, 1.0/n), G(n*(int64_t)n);
    NS s(n, n);
    auto t0 = chrono::steady_clock::now();
    int it = s.solve(a.data(), b.data(), M.data(), G.data(), 100000);
    auto t1 = chrono::steady_clock::now();
    double ms = chrono::duration<double, milli>(t1-t0).count();
    double cost = 0, mass = 0;
    for (int i = 0; i < n; ++i) {
        double rs = 0, cs = 0;
        for (int j = 0; j < n; ++j) { rs += G[i*(int64_t)n+j]; cost += G[i*(int64_t)n+j]*M[i*(int64_t)n+j]; }
        mass += rs;
    }
    printf("it=%d time=%.1f ms mass=%.6f cost=%.6f\n", it, ms, mass, cost);
}
