            vector<int> path; for(int x=in_S;;x=parent[x]){ path.push_back(x); if(x==leave) break; }
            struct Arc{int ts,tt,td; double f;};
            vector<Arc> arcs(path.size());
            for(size_t k=0;k+1<path.size();++k) arcs[k]={tsrc[path[k]],ttgt[path[k]],tdir[path[k]],flow[path[k]]};
            for(size_t k=0;k+1<path.size();++k) unlink(path[k]);
            unlink(leave);
            for(size_t k=0;k+1<path.size();++k){
                link_child(path[k], path[k+1]);
                tsrc[path[k+1]]=arcs[k].ts; ttgt[path[k+1]]=arcs[k].tt;
                tdir[path[k+1]]=-arcs[k].td; flow[path[k+1]]=arcs[k].f;
            }
            link_child(out_S, in_S);
            if(kind==0){ tsrc[in_S]=ei; ttgt[in_S]=ej; } else tsrc[in_S]=ttgt[in_S]=-1;
            tdir[in_S] = (in_S==u)? +1 : -1;
            flow[in_S] = delta;
            vector<int> st={in_S}; depth[in_S]=depth[out_S]+1;
            while(!st.empty()){ int v=st.back(); st.pop_back();
                for(int c=head_child[v];c!=-1;c=next_sib[c]){ depth[c]=depth[v]+1; st.push_back(c);} }
            recompute_sub();
            update_potentials_full();
            // numerical cleanup
            for(int v=0; v<N; ++v) if(fabs(flow[v])<1e-15) flow[v]=0;
        }
        memset(G,0,sizeof(double)*(size_t)n*m);
        double cost=0;
        for(int v=0; v<N; ++v) if(v!=root && tsrc[v]>=0){
            G[(int64_t)tsrc[v]*m+ttgt[v]] = flow[v];
            cost += flow[v]*cost_at(tsrc[v], ttgt[v]);
        }
        cost_out=cost;
        return it;
    }
};

int main(int argc, char** argv){
    int n = argc>1? atoi(argv[1]) : 30;
    int seed = argc>2? atoi(argv[2]) : 1;
    mt19937 rng(seed);
    uniform_real_distribution<double> U(0,1);
    vector<double> sp(2*n), tp(2*n);
    for(auto& x: sp) x=U(rng); for(auto& x: tp) x=U(rng);
    vector<double> M((int64_t)n*n);
    for(int i=0;i<n;i++) for(int j=0;j<n;j++){
        double dx=sp[2*i]-tp[2*j], dy=sp[2*i+1]-tp[2*j+1];
        M[(int64_t)i*n+j]=sqrt(dx*dx+dy*dy);
    }
    vector<double> a(n,1.0/n), b(n,1.0/n), G((int64_t)n*n);
    NS s(n,n);
    auto t0=chrono::steady_clock::now();
    double cost=0;
    int it=s.solve(a.data(), b.data(), M.data(), G.data(), 1000000, cost);
    double ms=chrono::duration<double,milli>(chrono::steady_clock::now()-t0).count();
    // write G and M for python compare? just print summary and dump G to file
    FILE* f=fopen("plan.bin","wb");
    fwrite(G.data(), sizeof(double), (size_t)n*n, f); fclose(f);
    FILE* fm=fopen("M.bin","wb");
    fwrite(M.data(), sizeof(double), (size_t)n*n, fm); fclose(fm);
    double mass=0; for(double x: G) mass+=x;
    printf("n=%d it=%d time=%.1f ms mass=%.6f cost=%.8f\n", n, it, ms, mass, cost);
}
