// Fast transportation network simplex.
// Entering arc search restricted to k-nearest candidates per row and column,
// with periodic full certification. Flow recomputed from supplies each pivot
// (correctness over micro-efficiency; pivot count is small).
#include <cstdio>
#include <cstdint>
#include <cmath>
#include <vector>
#include <cstring>
#include <algorithm>
#include <chrono>
#include <random>
#include <numeric>
using namespace std;

struct NS {
    int n, m, N, root, K;
    const double* M; double BIG;
    vector<int> parent, depth, head_child, next_sib, prev_sib;
    vector<int> tsrc, ttgt, tdir;
    vector<double> flow, pot, supply;
    // candidate lists
    vector<int> cand_row; // n * K
    vector<int> cand_col; // m * K (source indices)

    NS(int n_, int m_, int K_): n(n_), m(m_), K(K_) {
        N=n+m+1; root=n+m;
        parent.resize(N); depth.resize(N); head_child.resize(N);
        next_sib.resize(N); prev_sib.resize(N);
        tsrc.resize(N); ttgt.resize(N); tdir.resize(N);
        flow.resize(N); pot.resize(N); supply.resize(N);
        cand_row.resize((size_t)n*K);
        cand_col.resize((size_t)m*K);
    }
    inline double cost_at(int i,int j) const { return M[(int64_t)i*m+j]; }
    void link_child(int p,int c){ parent[c]=p; prev_sib[c]=-1; next_sib[c]=head_child[p];
        if(head_child[p]!=-1) prev_sib[head_child[p]]=c; head_child[p]=c; }
    void unlink(int v){ int p=parent[v]; int a=prev_sib[v], b=next_sib[v];
        if(a!=-1) next_sib[a]=b; else head_child[p]=b; if(b!=-1) prev_sib[b]=a;
        next_sib[v]=prev_sib[v]=-1; }

    void build_candidates(){
        vector<int> idx(max(n,m));
        for(int i=0;i<n;++i){
            iota(idx.begin(), idx.begin()+m, 0);
            const double* row=M+(int64_t)i*m;
            int kk=min(K,m);
            nth_element(idx.begin(), idx.begin()+kk, idx.begin()+m,
                        [&](int a,int b){return row[a]<row[b];});
            sort(idx.begin(), idx.begin()+kk, [&](int a,int b){return row[a]<row[b];});
            for(int t=0;t<K;++t) cand_row[(size_t)i*K+t] = idx[t%kk];
        }
        for(int j=0;j<m;++j){
            iota(idx.begin(), idx.begin()+n, 0);
            auto colcost=[&](int i){return M[(int64_t)i*m+j];};
            int kk=min(K,n);
            nth_element(idx.begin(), idx.begin()+kk, idx.begin()+n,
                        [&](int a,int b){return colcost(a)<colcost(b);});
            for(int t=0;t<K;++t) cand_col[(size_t)j*K+t] = idx[t%kk];
        }
    }

    void init(const double* a, const double* b, const double* M_){
        M=M_; BIG=0; for(int64_t k=0;k<(int64_t)n*m;++k) if(M[k]>BIG) BIG=M[k]; BIG+=1;
        fill(head_child.begin(),head_child.end(),-1);
        fill(next_sib.begin(),next_sib.end(),-1);
        fill(prev_sib.begin(),prev_sib.end(),-1);
        parent[root]=-1; depth[root]=0; pot[root]=0; supply[root]=0;
        for(int i=0;i<n;++i) supply[i]=a[i];
        for(int j=0;j<m;++j) supply[n+j]=-b[j];
        for(int i=n-1;i>=0;--i){ link_child(root,i); depth[i]=1; tsrc[i]=ttgt[i]=-1; tdir[i]=+1; pot[i]=BIG; }
        for(int j=m-1;j>=0;--j){ int v=n+j; link_child(root,v); depth[v]=1; tsrc[v]=ttgt[v]=-1; tdir[v]=-1; pot[v]=-BIG; }
        recompute_flows();
        build_candidates();
    }
    void recompute_flows(){
        vector<double> net(N);
        for(int v=0; v<N; ++v) net[v]=supply[v];
        vector<int> order; order.reserve(N); vector<int> st={root};
        while(!st.empty()){ int v=st.back(); st.pop_back(); order.push_back(v);
            for(int c=head_child[v]; c!=-1; c=next_sib[c]) st.push_back(c); }
        for(int k=(int)order.size()-1;k>=0;--k){ int v=order[k]; if(v!=root) net[parent[v]] += net[v]; }
        for(int v=0; v<N; ++v) if(v!=root) flow[v] = (tdir[v]==+1)? net[v] : -net[v];
    }
    void update_potentials_full(){
        pot[root]=0; vector<int> st; st.reserve(N); st.push_back(root);
        while(!st.empty()){ int v=st.back(); st.pop_back();
            for(int c=head_child[v]; c!=-1; c=next_sib[c]){
                double c_cost = (tsrc[c]==-1)? BIG : cost_at(tsrc[c], ttgt[c]);
                pot[c] = (tdir[c]==+1)? pot[v]+c_cost : pot[v]-c_cost;
                st.push_back(c);
            } }
    }

    // search: mode 0 = candidates only, mode 1 = full
    bool find_entering(int& ei,int& ej,int& kind, int mode){
        double best=-1e-9; ei=ej=-1; kind=-1;
        if(mode==0){
            for(int i=0;i<n;++i){
                double pi=pot[i]; const double* row=M+(int64_t)i*m;
                const int* cr=&cand_row[(size_t)i*K];
                for(int t=0;t<K;++t){ int j=cr[t]; double rc=row[j]-pi+pot[n+j];
                    if(rc<best){ best=rc; ei=i; ej=j; kind=0; } }
            }
            for(int j=0;j<m;++j){
                double pj=pot[n+j];
                const int* cc=&cand_col[(size_t)j*K];
                for(int t=0;t<K;++t){ int i=cc[t]; double rc=M[(int64_t)i*m+j]-pot[i]+pj;
                    if(rc<best){ best=rc; ei=i; ej=j; kind=0; } }
            }
        } else {
            for(int i=0;i<n;++i){ double pi=pot[i]; const double* row=M+(int64_t)i*m;
                for(int j=0;j<m;++j){ double rc=row[j]-pi+pot[n+j];
                    if(rc<best){ best=rc; ei=i; ej=j; kind=0; } } }
        }
        for(int i=0;i<n;++i){ if(parent[i]==root && tsrc[i]==-1) continue;
            double rc=BIG-pot[i]+pot[root]; if(rc<best){best=rc; ei=i; ej=-1; kind=1;} }
        for(int j=0;j<m;++j){ int v=n+j; if(parent[v]==root && tsrc[v]==-1) continue;
            double rc=BIG-pot[root]+pot[v]; if(rc<best){best=rc; ei=-1; ej=j; kind=2;} }
        return kind!=-1;
    }

    bool pivot(int ei,int ej,int kind){
        int u,w;
        if(kind==0){ u=ei; w=n+ej; } else if(kind==1){ u=ei; w=root; } else { u=root; w=n+ej; }
        vector<int> anc(N,0); for(int x=u;x!=-1;x=parent[x]) anc[x]=1;
        int lca=w; while(lca!=-1 && !anc[lca]) lca=parent[lca];
        double delta=1e300; int leave=-1;
        auto cons=[&](int x){ double cap=flow[x];
            if(cap<delta-1e-15 || (fabs(cap-delta)<=1e-15 && (leave<0||x<leave))){ delta=cap; leave=x; } };
        for(int x=u;x!=lca;x=parent[x]) if(tdir[x]==+1) cons(x);
        for(int x=w;x!=lca;x=parent[x]) if(tdir[x]==-1) cons(x);
        if(leave<0) return false;
        bool u_in_S=false; for(int x=u;x!=-1;x=parent[x]) if(x==leave){u_in_S=true;break;}
        int in_S = u_in_S? u : w;
        int out_S = u_in_S? w : u;
        vector<int> path; for(int x=in_S;;x=parent[x]){ path.push_back(x); if(x==leave) break; }
        struct Arc{int ts,tt,td;};
        vector<Arc> arcs(path.size());
        for(size_t k=0;k+1<path.size();++k) arcs[k]={tsrc[path[k]],ttgt[path[k]],tdir[path[k]]};
        for(size_t k=0;k+1<path.size();++k) unlink(path[k]);
        unlink(leave);
        for(size_t k=0;k+1<path.size();++k){
            link_child(path[k], path[k+1]);
            tsrc[path[k+1]]=arcs[k].ts; ttgt[path[k+1]]=arcs[k].tt; tdir[path[k+1]]=-arcs[k].td;
        }
        link_child(out_S, in_S);
        if(kind==0){ tsrc[in_S]=ei; ttgt[in_S]=ej; } else tsrc[in_S]=ttgt[in_S]=-1;
        tdir[in_S] = (in_S==u)? +1 : -1;
        vector<int> st={in_S}; depth[in_S]=depth[out_S]+1;
        while(!st.empty()){ int v=st.back(); st.pop_back();
            for(int c=head_child[v];c!=-1;c=next_sib[c]){ depth[c]=depth[v]+1; st.push_back(c);} }
        recompute_flows();
        update_potentials_full();
        return true;
    }

    int solve(const double* a,const double* b,const double* M_,double* G,int max_iter,double& cost_out){
        init(a,b,M_);
        int it=0, since_full=0;
        for(; it<max_iter; ++it){
            int ei,ej,kind;
            bool found = find_entering(ei,ej,kind, 0);
            if(!found){
                // certify
                if(!find_entering(ei,ej,kind, 1)) break;
            }
            if(!pivot(ei,ej,kind)) return -1;
        }
        memset(G,0,sizeof(double)*(size_t)n*m);
        double cost=0;
        for(int v=0; v<N; ++v) if(v!=root && tsrc[v]>=0){
            G[(int64_t)tsrc[v]*m+ttgt[v]] = flow[v];
            cost += flow[v]*cost_at(tsrc[v], ttgt[v]);
        }
        cost_out=cost;
        return it;
    }
};

int main(int argc, char** argv){
    int n = argc>1? atoi(argv[1]) : 200;
    int seed = argc>2? atoi(argv[2]) : 1;
    int K = argc>3? atoi(argv[3]) : 16;
    mt19937 rng(seed);
    uniform_real_distribution<double> U(0,1);
    vector<double> sp(2*n), tp(2*n);
    for(auto& x: sp) x=U(rng); for(auto& x: tp) x=U(rng);
    vector<double> M((int64_t)n*n);
    for(int i=0;i<n;i++) for(int j=0;j<n;j++){
        double dx=sp[2*i]-tp[2*j], dy=sp[2*i+1]-tp[2*j+1];
        M[(int64_t)i*n+j]=sqrt(dx*dx+dy*dy);
    }
    vector<double> a(n,1.0/n), b(n,1.0/n), G((int64_t)n*n);
    NS s(n,n,K);
    auto t0=chrono::steady_clock::now();
    double cost=0;
    int it=s.solve(a.data(), b.data(), M.data(), G.data(), 1000000, cost);
    double ms=chrono::duration<double,milli>(chrono::steady_clock::now()-t0).count();
    FILE* f=fopen("plan.bin","wb"); fwrite(G.data(), sizeof(double), (size_t)n*n, f); fclose(f);
    FILE* fm=fopen("M.bin","wb"); fwrite(M.data(), sizeof(double), (size_t)n*n, fm); fclose(fm);
    printf("n=%d K=%d it=%d time=%.1f ms cost=%.8f\n", n, K, it, ms, cost);
}
