// Network simplex with a k-nearest feasible initial basis (greedy), then optimize.
// Flow recomputed exactly each pivot. Candidate pricing + full certification.
#include <cstdio>
#include <cstdint>
#include <cmath>
#include <vector>
#include <cstring>
#include <algorithm>
#include <chrono>
#include <random>
#include <numeric>
#include <queue>
using namespace std;

struct Edge { int i,j; double c; };

struct NS {
    int n, m, N, root, K;
    const double* M; double BIG;
    vector<int> parent, depth, head_child, next_sib, prev_sib;
    vector<int> tsrc, ttgt, tdir;
    vector<double> flow, pot, supply, net;
    vector<int> cand_row, cand_col;

    NS(int n_, int m_, int K_): n(n_), m(m_), K(K_) {
        N=n+m+1; root=n+m;
        parent.resize(N); depth.resize(N); head_child.resize(N);
        next_sib.resize(N); prev_sib.resize(N);
        tsrc.resize(N); ttgt.resize(N); tdir.resize(N);
        flow.resize(N); pot.resize(N); supply.resize(N); net.resize(N);
        cand_row.resize((size_t)n*K); cand_col.resize((size_t)m*K);
    }
    inline double cost_at(int i,int j) const { return M[(int64_t)i*m+j]; }
    void link_child(int p,int c){ parent[c]=p; prev_sib[c]=-1; next_sib[c]=head_child[p];
        if(head_child[p]!=-1) prev_sib[head_child[p]]=c; head_child[p]=c; }
    void unlink(int v){ int p=parent[v]; int a=prev_sib[v], b=next_sib[v];
        if(a!=-1) next_sib[a]=b; else head_child[p]=b; if(b!=-1) prev_sib[b]=a;
        next_sib[v]=prev_sib[v]=-1; }

    void build_candidates(){
        vector<int> idx(max(n,m));
        for(int i=0;i<n;++i){
            iota(idx.begin(), idx.begin()+m, 0);
            const double* row=M+(int64_t)i*m;
            int kk=min(K,m);
            nth_element(idx.begin(), idx.begin()+kk-1, idx.begin()+m, [&](int a,int b){return row[a]<row[b];});
            for(int t=0;t<K;++t) cand_row[(size_t)i*K+t]=idx[t%kk];
        }
        for(int j=0;j<m;++j){
            iota(idx.begin(), idx.begin()+n, 0);
            int kk=min(K,n);
            nth_element(idx.begin(), idx.begin()+kk-1, idx.begin()+n,
                [&](int a,int b){return M[(int64_t)a*m+j]<M[(int64_t)b*m+j];});
            for(int t=0;t<K;++t) cand_col[(size_t)j*K+t]=idx[t%kk];
        }
