        // union-find over sources+targets (0..n+m-1)
        int nm=n+m;
        vector<int> uf(nm); iota(uf.begin(), uf.end(), 0);
        function<int(int)> find=[&](int x){ return uf[x]==x? x : uf[x]=find(uf[x]); };
        // candidate edges sorted by cost
        struct E{double c; int i,j;};
        vector<E> edges; edges.reserve((size_t)(n+m)*K);
        vector<char> seen((size_t)n*m, 0);
        for(int i=0;i<n;++i) for(int t=0;t<K;++t){ int j=cand_row[(size_t)i*K+t];
            size_t id=(size_t)i*m+j; if(!seen[id]){ seen[id]=1; edges.push_back({cost_at(i,j), i, j}); } }
        for(int j=0;j<m;++j) for(int t=0;t<K;++t){ int i=cand_col[(size_t)j*K+t];
            size_t id=(size_t)i*m+j; if(!seen[id]){ seen[id]=1; edges.push_back({cost_at(i,j), i, j}); } }
        sort(edges.begin(), edges.end(), [](const E& a,const E& b){return a.c<b.c;});

        // We need a spanning tree, not just a forest of the support. Use Kruskal to get
        // a spanning tree over all nodes, adding artificial edges (cost BIG) to connect
        // leftovers through root. But root is extra. Simpler: build forest with Kruskal
        // on real edges, then connect every component to root with an artificial edge.
        // That gives a spanning tree of all nodes+root. Good, feasible basis (flows
        // recomputed from supplies; artificial edges carry the imbalance).
        vector<pair<int,int>> tree_edges; // real edges (i, j_node) where j_node = n+j
        for(auto& e: edges){
            int x=find(e.i), y=find(n+e.j);
            if(x!=y){ uf[x]=y; tree_edges.push_back({e.i, n+e.j}); }
        }
        // connect components to root
        vector<int> comp_root(nm, -1);
        // build adjacency of chosen real edges and attach
        vector<vector<int>> adj(nm);
        for(auto [u,v]: tree_edges){ adj[u].push_back(v); adj[v].push_back(u); }
        vector<char> vis(nm, 0);
        for(int s0=0;s0<nm;++s0) if(!vis[s0]){
            // BFS component, root the tree at s0, then attach s0 to artificial root
            vector<int> order; order.push_back(s0); vis[s0]=1;
            parent[s0]=root; tsrc[s0]=ttgt[s0]=-1;
            // artificial orientation: source node -> root (tdir+1) or root -> target (tdir-1)
            tdir[s0] = (s0<n)? +1 : -1;
            link_child(root, s0); depth[s0]=1;
            for(size_t q=0; q<order.size(); ++q){
                int u=order[q];
                for(int v: adj[u]) if(!vis[v]){
                    vis[v]=1; order.push_back(v);
                    link_child(u, v); parent[v]=u; depth[v]=depth[u]+1;
                    // real edge between u and v: one is source (<n), one is target (>=n)
                    int src = (u<n)? u : v;
                    int tgt = (u<n)? (v-n) : (u-n);
                    tsrc[v]=src; ttgt[v]=tgt;
                    // natural dir source->target. child is v, parent is u.
                    // tdir +1 if natural dir is child->parent, i.e. child is source.
                    tdir[v] = (v<n)? +1 : -1;
                }
            }
        }
        recompute_flows();
        update_potentials_full();
    }

    void recompute_flows(){
        for(int v=0; v<N; ++v) net[v]=supply[v];
        vector<int> order; order.reserve(N); vector<int> st={root};
        while(!st.empty()){ int v=st.back(); st.pop_back(); order.push_back(v);
            for(int c=head_child[v]; c!=-1; c=next_sib[c]) st.push_back(c); }
        for(int k=(int)order.size()-1;k>=0;--k){ int v=order[k]; if(v!=root) net[parent[v]] += net[v]; }
        for(int v=0; v<N; ++v) if(v!=root) flow[v] = (tdir[v]==+1)? net[v] : -net[v];
    }
    void update_potentials_full(){
        pot[root]=0; vector<int> st; st.reserve(N); st.push_back(root);
        while(!st.empty()){ int v=st.back(); st.pop_back();
            for(int c=head_child[v]; c!=-1; c=next_sib[c]){
                double c_cost = (tsrc[c]==-1)? BIG : cost_at(tsrc[c], ttgt[c]);
                pot[c] = (tdir[c]==+1)? pot[v]+c_cost : pot[v]-c_cost;
                st.push_back(c);
            } }
    }
    bool find_entering(int& ei,int& ej,int& kind, int mode){
        double best=-1e-9; ei=ej=-1; kind=-1;
        if(mode==0){
            for(int i=0;i<n;++i){ double pi=pot[i]; const double* row=M+(int64_t)i*m;
                const int* cr=&cand_row[(size_t)i*K];
                for(int t=0;t<K;++t){ int j=cr[t]; double rc=row[j]-pi+pot[n+j];
                    if(rc<best){ best=rc; ei=i; ej=j; kind=0; } } }
            for(int j=0;j<m;++j){ double pj=pot[n+j]; const int* cc=&cand_col[(size_t)j*K];
                for(int t=0;t<K;++t){ int i=cc[t]; double rc=M[(int64_t)i*m+j]-pot[i]+pj;
                    if(rc<best){ best=rc; ei=i; ej=j; kind=0; } } }
        } else {
            for(int i=0;i<n;++i){ double pi=pot[i]; const double* row=M+(int64_t)i*m;
                for(int j=0;j<m;++j){ double rc=row[j]-pi+pot[n+j];
                    if(rc<best){ best=rc; ei=i; ej=j; kind=0; } } }
        }
        for(int i=0;i<n;++i){ if(parent[i]==root && tsrc[i]==-1) continue;
            double rc=BIG-pot[i]; if(rc<best){best=rc; ei=i; ej=-1; kind=1;} }
        for(int j=0;j<m;++j){ int v=n+j; if(parent[v]==root && tsrc[v]==-1) continue;
            double rc=BIG+pot[v]; if(rc<best){best=rc; ei=-1; ej=j; kind=2;} }
        return kind!=-1;
    }
    bool pivot(int ei,int ej,int kind){
        int u,w;
        if(kind==0){ u=ei; w=n+ej; } else if(kind==1){ u=ei; w=root; } else { u=root; w=n+ej; }
        vector<int> anc(N,0); for(int x=u;x!=-1;x=parent[x]) anc[x]=1;
        int lca=w; while(lca!=-1 && !anc[lca]) lca=parent[lca];
        double delta=1e300; int leave=-1;
        auto cons=[&](int x){ double cap=flow[x];
            if(cap<delta-1e-12 || (fabs(cap-delta)<=1e-12 && (leave<0||x<leave))){ delta=cap; leave=x; } };
        for(int x=u;x!=lca;x=parent[x]) if(tdir[x]==+1) cons(x);
        for(int x=w;x!=lca;x=parent[x]) if(tdir[x]==-1) cons(x);
        if(leave<0 || delta<0) return false;
        bool u_in_S=false; for(int x=u;x!=-1;x=parent[x]) if(x==leave){u_in_S=true;break;}
        int in_S = u_in_S? u : w;
        int out_S = u_in_S? w : u;
        vector<int> path; for(int x=in_S;;x=parent[x]){ path.push_back(x); if(x==leave) break; }
        struct Arc{int ts,tt,td;};
        vector<Arc> arcs(path.size());
        for(size_t k=0;k+1<path.size();++k) arcs[k]={tsrc[path[k]],ttgt[path[k]],tdir[path[k]]};
        for(size_t k=0;k+1<path.size();++k) unlink(path[k]);
        unlink(leave);
        for(size_t k=0;k+1<path.size();++k){
            link_child(path[k], path[k+1]);
            tsrc[path[k+1]]=arcs[k].ts; ttgt[path[k+1]]=arcs[k].tt; tdir[path[k+1]]=-arcs[k].td;
        }
        link_child(out_S, in_S);
        if(kind==0){ tsrc[in_S]=ei; ttgt[in_S]=ej; } else tsrc[in_S]=ttgt[in_S]=-1;
        tdir[in_S]=(in_S==u)? +1 : -1;
        vector<int> st={in_S}; depth[in_S]=depth[out_S]+1;
        while(!st.empty()){ int v=st.back(); st.pop_back();
            for(int c=head_child[v];c!=-1;c=next_sib[c]){ depth[c]=depth[v]+1; st.push_back(c);} }
        recompute_flows();
        update_potentials_full();
        return true;
    }
    int solve(const double* a,const double* b,const double* M_,double* G,int max_iter,double& cost_out){
        auto t0=chrono::steady_clock::now();
        init(a,b,M_);
        double ms_init=chrono::duration<double,milli>(chrono::steady_clock::now()-t0).count();
        int it=0;
        for(; it<max_iter; ++it){
            int ei,ej,kind;
            if(!find_entering(ei,ej,kind,0)){
                if(!find_entering(ei,ej,kind,1)) break;
            }
            if(!pivot(ei,ej,kind)){ fprintf(stderr,"pivot fail it %d\n", it); return -1; }
        }
        fprintf(stderr, "init %.1f ms iters %d\n", ms_init, it);
        memset(G,0,sizeof(double)*(size_t)n*m);
        double cost=0;
        for(int v=0; v<N; ++v) if(v!=root && tsrc[v]>=0 && flow[v]>1e-15){
            G[(int64_t)tsrc[v]*m+ttgt[v]] = flow[v];
            cost += flow[v]*cost_at(tsrc[v], ttgt[v]);
        }
        cost_out=cost;
        return it;
    }
};

int main(int argc, char** argv){
    int n = argc>1? atoi(argv[1]) : 200;
    int seed = argc>2? atoi(argv[2]) : 1;
    int K = argc>3? atoi(argv[3]) : 16;
    mt19937 rng(seed);
    uniform_real_distribution<double> U(0,1);
    vector<double> sp(2*n), tp(2*n);
    for(auto& x: sp) x=U(rng); for(auto& x: tp) x=U(rng);
    vector<double> M((int64_t)n*n);
    for(int i=0;i<n;i++) for(int j=0;j<n;j++){
        double dx=sp[2*i]-tp[2*j], dy=sp[2*i+1]-tp[2*j+1];
        M[(int64_t)i*n+j]=sqrt(dx*dx+dy*dy);
    }
    vector<double> a(n,1.0/n), b(n,1.0/n), G((int64_t)n*n);
    NS s(n,n,K);
    auto t0=chrono::steady_clock::now();
    double cost=0;
    int it=s.solve(a.data(), b.data(), M.data(), G.data(), 1000000, cost);
    double ms=chrono::duration<double,milli>(chrono::steady_clock::now()-t0).count();
    FILE* f=fopen("plan.bin","wb"); fwrite(G.data(), sizeof(double), (size_t)n*n, f); fclose(f);
    FILE* fm=fopen("M.bin","wb"); fwrite(M.data(), sizeof(double), (size_t)n*n, fm); fclose(fm);
    printf("n=%d K=%d it=%d time=%.1f ms cost=%.8f\n", n, K, it, ms, cost);
}
