// Feasible basic solution via greedy on k-nearest edges, then basic tree = support + artificial.
// Measure cost gap to optimum and construction time. No simplex yet.
#include <cstdio>
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <chrono>
#include <random>
#include <numeric>
using namespace std;

int main(int argc, char** argv){
    int n=argc>1?atoi(argv[1]):400;
    int seed=argc>2?atoi(argv[2]):1;
    int K=argc>3?atoi(argv[3]):32;
    mt19937 rng(seed);
    uniform_real_distribution<double> U(0,1);
    vector<double> sp(2*n), tp(2*n);
    for(auto& x:sp) x=U(rng); for(auto& x:tp) x=U(rng);
    vector<double> M((int64_t)n*n);
    for(int i=0;i<n;i++) for(int j=0;j<n;j++){
        double dx=sp[2*i]-tp[2*j], dy=sp[2*i+1]-tp[2*j+1];
        M[(int64_t)i*n+j]=sqrt(dx*dx+dy*dy);
    }
    vector<double> as(n,1.0/n), bs(n,1.0/n);
    auto t0=chrono::steady_clock::now();
    // candidate edges
    struct E{double c; int i,j;};
    vector<E> edges; edges.reserve((size_t)n*K*2);
    vector<int> idx(n);
    for(int i=0;i<n;i++){
        iota(idx.begin(),idx.end(),0);
        const double* row=&M[(int64_t)i*n];
        nth_element(idx.begin(), idx.begin()+K-1, idx.end(), [&](int a,int b){return row[a]<row[b];});
        for(int t=0;t<K;t++) edges.push_back({row[idx[t]], i, idx[t]});
    }
    sort(edges.begin(), edges.end(), [](const E&a,const E&b){return a.c<b.c;});
    vector<double> ra=as, rb=bs;
    double cost=0; int used=0;
    vector<tuple<int,int,double>> flows;
    for(auto& e: edges){
        double f=min(ra[e.i], rb[e.j]);
        if(f>1e-15){ ra[e.i]-=f; rb[e.j]-=f; cost+=f*e.c; used++; flows.push_back({e.i,e.j,f}); }
    }
    double left=0; for(double x: ra) left+=x;
    double ms=chrono::duration<double,milli>(chrono::steady_clock::now()-t0).count();
    printf("n=%d K=%d edges %zu used %d residual_mass %.6f cost %.6f time %.1f ms\n",
        n, K, edges.size(), used, left, cost, ms);
}
