// Lean transportation network simplex. Artificial-root start, Dantzig pivot,
// no per-iteration heap allocation, contiguous arrays.
#include <cstdio>
#include <cstdint>
#include <cmath>
#include <vector>
#include <cstring>
#include <algorithm>
#include <chrono>
#include <random>
using namespace std;

struct NS {
    int n, m, N, root;
    const double* M;
    double BIG, eps;
    int *parent, *depth, *head, *nexts, *prevs;
    int *tsrc, *ttgt, *tdir;
    double *flow, *pot, *supply, *net;
    int *order; // size N scratch
    int *anc;   // size N scratch

    NS(int n_, int m_): n(n_), m(m_) {
        N=n+m+1; root=n+m; eps=1e-12;
        parent=new int[N]; depth=new int[N]; head=new int[N]; nexts=new int[N]; prevs=new int[N];
        tsrc=new int[N]; ttgt=new int[N]; tdir=new int[N];
        flow=new double[N]; pot=new double[N]; supply=new double[N]; net=new double[N];
        order=new int[N]; anc=new int[N];
    }
    ~NS(){ delete[] parent; delete[] depth; delete[] head; delete[] nexts; delete[] prevs;
           delete[] tsrc; delete[] ttgt; delete[] tdir; delete[] flow; delete[] pot;
           delete[] supply; delete[] net; delete[] order; delete[] anc; }
    inline double C(int i,int j) const { return M[(int64_t)i*m+j]; }

    inline void link(int p,int c){ parent[c]=p; prevs[c]=-1; nexts[c]=head[p];
        if(head[p]!=-1) prevs[head[p]]=c; head[p]=c; }
    inline void unlink(int v){ int p=parent[v], a=prevs[v], b=nexts[v];
        if(a!=-1) nexts[a]=b; else head[p]=b; if(b!=-1) prevs[b]=a; nexts[v]=prevs[v]=-1; }

    void recompute_flows(){
        for(int v=0; v<N; ++v) net[v]=supply[v];
        int osz=0; order[osz++]=root;
        for(int q=0; q<osz; ++q){ int v=order[q]; for(int c=head[v]; c!=-1; c=nexts[c]) order[osz++]=c; }
        for(int k=osz-1; k>=0; --k){ int v=order[k]; if(v!=root) net[parent[v]] += net[v]; }
        for(int v=0; v<N; ++v) if(v!=root) flow[v] = (tdir[v]==1)? net[v] : -net[v];
    }
    void update_pot(){
        pot[root]=0;
        int osz=0; order[osz++]=root;
        for(int q=0; q<osz; ++q){
            int v=order[q];
            for(int c=head[v]; c!=-1; c=nexts[c]){
                double cc = (tsrc[c]<0)? BIG : C(tsrc[c], ttgt[c]);
                pot[c] = (tdir[c]==1)? pot[v]+cc : pot[v]-cc;
                order[osz++]=c;
            }
        }
    }
    void init(const double* a, const double* b, const double* M_){
        M=M_;
        BIG=0; for(int64_t k=0, nm=(int64_t)n*m; k<nm; ++k) if(M[k]>BIG) BIG=M[k];
        BIG+=1.0;
        memset(head, 0xFF, sizeof(int)*N);
        memset(nexts, 0xFF, sizeof(int)*N);
        memset(prevs, 0xFF, sizeof(int)*N);
        parent[root]=-1; depth[root]=0; pot[root]=0; supply[root]=0;
        for(int i=0;i<n;++i) supply[i]=a[i];
        for(int j=0;j<m;++j) supply[n+j]=-b[j];
        for(int i=n-1;i>=0;--i){ link(root,i); depth[i]=1; tsrc[i]=ttgt[i]=-1; tdir[i]=1; pot[i]=BIG; }
        for(int j=m-1;j>=0;--j){ int v=n+j; link(root,v); depth[v]=1; tsrc[v]=ttgt[v]=-1; tdir[v]=-1; pot[v]=-BIG; }
        recompute_flows();
    }

    // returns false if optimal
    bool find_entering(int& ei, int& ej, int& kind){
        double best=-eps; ei=ej=-1; kind=-1;
        for(int i=0;i<n;++i){
            double pi=pot[i];
            const double* row=M+(int64_t)i*m;
            double bj=best+pi;
            for(int j=0;j<m;++j){
                double rc=row[j]+pot[n+j];
                if(rc<bj){ bj=rc; best=rc-pi; ei=i; ej=j; kind=0; }
            }
        }
        double pr=pot[root];
        for(int i=0;i<n;++i){ if(parent[i]==root && tsrc[i]<0) continue;
            double rc=BIG-pot[i]+pr; if(rc<best){ best=rc; ei=i; ej=-1; kind=1; } }
        for(int j=0;j<m;++j){ int v=n+j; if(parent[v]==root && tsrc[v]<0) continue;
            double rc=BIG-pr+pot[v]; if(rc<best){ best=rc; ei=-1; ej=j; kind=2; } }
        return kind!=-1;
    }

    bool pivot(int ei,int ej,int kind){
        int u,w;
        if(kind==0){ u=ei; w=n+ej; } else if(kind==1){ u=ei; w=root; } else { u=root; w=n+ej; }
        memset(anc, 0, sizeof(int)*N);
        for(int x=u; x!=-1; x=parent[x]) anc[x]=1;
        int lca=w; while(!anc[lca]) lca=parent[lca];
        double delta=1e300; int leave=-1;
        for(int x=u; x!=lca; x=parent[x]) if(tdir[x]==1){ double cap=flow[x];
            if(cap<delta){ delta=cap; leave=x; } }
        for(int x=w; x!=lca; x=parent[x]) if(tdir[x]==-1){ double cap=flow[x];
            if(cap<delta){ delta=cap; leave=x; } }
        if(leave<0) return false;
        bool u_in_S=false; for(int x=u; x!=-1; x=parent[x]) if(x==leave){ u_in_S=true; break; }
        int in_S = u_in_S? u : w;
        int out_S = u_in_S? w : u;
        // path from in_S up to leave, stored in order[] (reused; flows already consistent)
        int plen=0; for(int x=in_S;; x=parent[x]){ order[plen++]=x; if(x==leave) break; }
        // snapshot arc identity into anc[] repurposed? use stack arrays via tsrc copy in local static buffers
        // path length <= N. Use the upper half? We have no extra buffer. Use heap-free: store in
        // prevs temporarily? No, prevs is live. Allocate once: reuse `depth` is live.
        // We'll copy arc data into a small static thread-local buffer sized on demand — use members? 
        // Simpler: store snapshot in parallel arrays allocated once. See pivot_buf added below.
        return pivot_rehang(u, w, ei, ej, kind, in_S, out_S, leave, plen);
    }

    int *snap_ts, *snap_tt, *snap_td;
    void ensure_snap(){ if(!snap_ts){ snap_ts=new int[N]; snap_tt=new int[N]; snap_td=new int[N]; } }

    bool pivot_rehang(int u,int w,int ei,int ej,int kind,int in_S,int out_S,int leave,int plen){
        ensure_snap();
        for(int k=0;k+1<plen;++k){ int node=order[k]; snap_ts[k]=tsrc[node]; snap_tt[k]=ttgt[node]; snap_td[k]=tdir[node]; }
        for(int k=0;k+1<plen;++k) unlink(order[k]);
        unlink(leave);
        for(int k=0;k+1<plen;++k){
            link(order[k], order[k+1]);
            tsrc[order[k+1]]=snap_ts[k]; ttgt[order[k+1]]=snap_tt[k]; tdir[order[k+1]]=-snap_td[k];
        }
        link(out_S, in_S);
        if(kind==0){ tsrc[in_S]=ei; ttgt[in_S]=ej; } else tsrc[in_S]=ttgt[in_S]=-1;
        tdir[in_S]=(in_S==u)? 1 : -1;
        depth[in_S]=depth[out_S]+1;
        int osz=0; order[osz++]=in_S;
        for(int q=0; q<osz; ++q){ int v=order[q];
            for(int c=head[v]; c!=-1; c=nexts[c]){ depth[c]=depth[v]+1; order[osz++]=c; } }
        recompute_flows();
        update_pot();
        return true;
    }

    int solve(const double* a,const double* b,const double* M_, double* G, int max_iter){
        snap_ts=snap_tt=snap_td=nullptr;
        init(a,b,M_);
        int it=0;
        for(; it<max_iter; ++it){
            int ei,ej,kind;
            if(!find_entering(ei,ej,kind)) break;
            if(!pivot(ei,ej,kind)) return -1;
        }
        memset(G, 0, sizeof(double)*(size_t)n*m);
        for(int v=0; v<N; ++v) if(v!=root && tsrc[v]>=0) G[(int64_t)tsrc[v]*m+ttgt[v]] = flow[v];
        return it;
    }
};

int main(int argc, char** argv){
