    }
    vector<double> a(n,1.0/n), b(n,1.0/n), G((int64_t)n*n);
    NS s(n,n);
    auto t0=chrono::steady_clock::now();
    int it=s.solve(a.data(), b.data(), M.data(), G.data(), 10000000);
    double ms=chrono::duration<double,milli>(chrono::steady_clock::now()-t0).count();
    double cost=0, mass=0, neg=0;
    for(int i=0;i<n;i++) for(int j=0;j<n;j++){ double g=G[(int64_t)i*n+j]; mass+=g; cost+=g*M[(int64_t)i*n+j]; if(g<neg) neg=g; }
    FILE* f=fopen("plan.bin","wb"); fwrite(G.data(),8,(size_t)n*n,f); fclose(f);
    FILE* fm=fopen("M.bin","wb"); fwrite(M.data(),8,(size_t)n*n,fm); fclose(fm);
    printf("n=%d it=%d time=%.1f ms mass=%.6f cost=%.8f neg=%.2e\n", n, it, ms, mass, cost, neg);
}
