// LEMON-style transportation network simplex:
//  - basic initial solution (each source linked to target 0 conceptually via
//    the standard "source i -> root, root -> target j" is replaced by the
//    LEMON basic init: connect source i to target (i % m) and fix supplies
//    with artificial root arcs only for imbalance). For equal-size uniform
//    marginals we use: source i connected to target i, flow 1/n. That is a
//    feasible basis with zero artificial flow. Then block-search pivots.
#include <cstdio>
#include <cstdint>
#include <cmath>
#include <vector>
#include <cstring>
#include <algorithm>
#include <chrono>
#include <random>
using namespace std;

struct NS {
    int n, m, N, root;
    const double* M;
    double BIG;
    int *parent, *head, *nexts, *prevs, *tsrc, *ttgt, *tdir, *depth;
    double *flow, *pot, *supply, *net;
    int *anc, *pathbuf, *snap_ts, *snap_tt, *snap_td;
    int block_size;

    NS(int n_, int m_): n(n_), m(m_) {
        N=n+m+1; root=n+m;
        auto ai=[](int k){return new int[k]();};
        parent=ai(N); head=ai(N); nexts=ai(N); prevs=ai(N);
        tsrc=ai(N); ttgt=ai(N); tdir=ai(N); depth=ai(N);
        anc=ai(N); pathbuf=ai(N); snap_ts=ai(N); snap_tt=ai(N); snap_td=ai(N);
        flow=new double[N](); pot=new double[N](); supply=new double[N](); net=new double[N]();
        block_size = max(1, (int)sqrt((double)n));
    }
    inline double C(int i,int j) const { return M[(int64_t)i*m+j]; }
    inline void link(int p,int c){ parent[c]=p; prevs[c]=-1; nexts[c]=head[p];
        if(head[p]!=-1) prevs[head[p]]=c; head[p]=c; }
    inline void unlink(int v){ int p=parent[v], a=prevs[v], b=nexts[v];
        if(a!=-1) nexts[a]=b; else head[p]=b; if(b!=-1) prevs[b]=a; nexts[v]=prevs[v]=-1; }

    void recompute_flows(){
        for(int v=0; v<N; ++v) net[v]=supply[v];
        int osz=0; pathbuf[osz++]=root;
        for(int q=0; q<osz; ++q){ int v=pathbuf[q]; for(int c=head[v]; c!=-1; c=nexts[c]) pathbuf[osz++]=c; }
        for(int k=osz-1; k>=0; --k){ int v=pathbuf[k]; if(v!=root) net[parent[v]] += net[v]; }
        for(int v=0; v<N; ++v) if(v!=root) flow[v] = (tdir[v]==1)? net[v] : -net[v];
    }
    void update_pot_full(){
        pot[root]=0; int osz=0; pathbuf[osz++]=root;
        for(int q=0; q<osz; ++q){ int v=pathbuf[q];
            for(int c=head[v]; c!=-1; c=nexts[c]){
                double cc=(tsrc[c]<0)? BIG : C(tsrc[c], ttgt[c]);
                pot[c]=(tdir[c]==1)? pot[v]+cc : pot[v]-cc;
                pathbuf[osz++]=c;
            } }
    }

    // Feasible basis: source i -> target (i % m) carries a[i] (only valid if
    // column sums match; for uniform equal size they do: each target j receives
    // a[j] from source j). Tree: root -- target j -- source j. Artificial arcs
    // root->target carry 0 flow. Real arc source->target.
    void init(const double* a, const double* b, const double* M_){
        M=M_; BIG=0;
        for(int64_t k=0, nm=(int64_t)n*m; k<nm; ++k) if(M[k]>BIG) BIG=M[k];
        BIG+=1.0;
        memset(head,0xFF,sizeof(int)*N); memset(nexts,0xFF,sizeof(int)*N); memset(prevs,0xFF,sizeof(int)*N);
        parent[root]=-1; depth[root]=0; pot[root]=0; supply[root]=0;
        for(int i=0;i<n;++i) supply[i]=a[i];
        for(int j=0;j<m;++j) supply[n+j]=-b[j];

