        double best=-1e-9; ei=ej=-1; kind=-1;
        for(int i=0;i<n;++i){ double pi=pot[i]; const double* row=M+(int64_t)i*m; const double* pj=pot+n;
            for(int j=0;j<m;++j){ double rc=row[j]-pi+pj[j]; if(rc<best){ best=rc; ei=i; ej=j; kind=0; } } }
        for(int i=0;i<n;++i){ if(parent[i]==root && tsrc[i]<0) continue;
            double rc=BIG-pot[i]; if(rc<best){ best=rc; ei=i; ej=-1; kind=1; } }
        for(int j=0;j<m;++j){ int v=n+j; if(parent[v]==root && tsrc[v]<0) continue;
            double rc=BIG+pot[v]; if(rc<best){ best=rc; ei=-1; ej=j; kind=2; } }
        return kind!=-1;
    }

    bool pivot(int ei,int ej,int kind){
        int u,w;
        if(kind==0){ u=ei; w=n+ej; } else if(kind==1){ u=ei; w=root; } else { u=root; w=n+ej; }
        memset(anc,0,sizeof(int)*N);
        for(int x=u; x!=-1; x=parent[x]) anc[x]=1;
        int lca=w; while(!anc[lca]) lca=parent[lca];
        double delta=1e300; int leave=-1;
        for(int x=u; x!=lca; x=parent[x]) if(tdir[x]==1 && flow[x]<delta){ delta=flow[x]; leave=x; }
        for(int x=w; x!=lca; x=parent[x]) if(tdir[x]==-1 && flow[x]<delta){ delta=flow[x]; leave=x; }
        if(leave<0) return false;
        bool u_in_S=false; for(int x=u; x!=-1; x=parent[x]) if(x==leave){ u_in_S=true; break; }
        int in_S=u_in_S? u:w, out_S=u_in_S? w:u;
        int plen=0; for(int x=in_S;; x=parent[x]){ pathbuf[plen++]=x; if(x==leave) break; }
        for(int k=0;k+1<plen;++k){ snap_ts[k]=tsrc[pathbuf[k]]; snap_tt[k]=ttgt[pathbuf[k]]; snap_td[k]=tdir[pathbuf[k]]; }
        for(int k=0;k+1<plen;++k) unlink(pathbuf[k]);
        unlink(leave);
        for(int k=0;k+1<plen;++k){ link(pathbuf[k], pathbuf[k+1]);
            tsrc[pathbuf[k+1]]=snap_ts[k]; ttgt[pathbuf[k+1]]=snap_tt[k]; tdir[pathbuf[k+1]]=-snap_td[k]; }
        link(out_S, in_S);
        if(kind==0){ tsrc[in_S]=ei; ttgt[in_S]=ej; } else tsrc[in_S]=ttgt[in_S]=-1;
        tdir[in_S]=(in_S==u)? 1 : -1;
        recompute_flows();
        update_pot_full();
        return true;
    }

    int solve(const double* a,const double* b,const double* M_, double* G, int max_iter){
        block_start=0;
        init(a,b,M_);
        int it=0, stall=0;
        for(; it<max_iter; ++it){
            int ei,ej,kind;
            if(!find_entering(ei,ej,kind)){
                stall++;
                if(stall> (n/block_size+2)){
                    if(!find_entering_full(ei,ej,kind)) break;
                } else continue;
            } else stall=0;
            if(!pivot(ei,ej,kind)) return -1;
        }
        memset(G,0,sizeof(double)*(size_t)n*m);
        for(int v=0; v<N; ++v) if(v!=root && tsrc[v]>=0) G[(int64_t)tsrc[v]*m+ttgt[v]] = flow[v];
        return it;
    }
};

int main(int argc, char** argv){
    int n=argc>1?atoi(argv[1]):200;
    int seed=argc>2?atoi(argv[2]):1;
    mt19937 rng(seed);
    uniform_real_distribution<double> U(0,1);
    vector<double> sp(2*n), tp(2*n);
    for(auto& x:sp) x=U(rng); for(auto& x:tp) x=U(rng);
    vector<double> M((int64_t)n*n);
    for(int i=0;i<n;i++) for(int j=0;j<n;j++){
        double dx=sp[2*i]-tp[2*j], dy=sp[2*i+1]-tp[2*j+1];
        M[(int64_t)i*n+j]=sqrt(dx*dx+dy*dy);
    }
    vector<double> a(n,1.0/n), b(n,1.0/n), G((int64_t)n*n);
    NS s(n,n);
    auto t0=chrono::steady_clock::now();
    int it=s.solve(a.data(), b.data(), M.data(), G.data(), 10000000);
    double ms=chrono::duration<double,milli>(chrono::steady_clock::now()-t0).count();
    double cost=0, mass=0, neg=0;
    for(int64_t k=0;k<(int64_t)n*n;++k){ mass+=G[k]; cost+=G[k]*M[k]; if(G[k]<neg) neg=G[k]; }
    FILE* f=fopen("plan.bin","wb"); fwrite(G.data(),8,(size_t)n*n,f); fclose(f);
    FILE* fm=fopen("M.bin","wb"); fwrite(M.data(),8,(size_t)n*n,fm); fclose(fm);
    printf("n=%d it=%d time=%.1f ms mass=%.6f cost=%.8f neg=%.2e\n", n, it, ms, mass, cost, neg);
}
