// Auction algorithm for the assignment problem (uniform 1/n masses -> assignment).
// eps-scaling. Reports cost and time; compares optimality roughly by printing cost.
#include <cstdio>
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <chrono>
#include <random>
#include <limits>
using namespace std;

int main(int argc, char** argv){
    int n=argc>1?atoi(argv[1]):400;
    int seed=argc>2?atoi(argv[2]):1;
    mt19937 rng(seed);
    uniform_real_distribution<double> U(0,1);
    vector<double> sp(2*n), tp(2*n);
    for(auto& x:sp) x=U(rng); for(auto& x:tp) x=U(rng);
    vector<double> M((int64_t)n*n);
    double Cmax=0;
    for(int i=0;i<n;i++) for(int j=0;j<n;j++){
        double dx=sp[2*i]-tp[2*j], dy=sp[2*i+1]-tp[2*j+1];
        double c=sqrt(dx*dx+dy*dy); M[(int64_t)i*n+j]=c; if(c>Cmax) Cmax=c;
    }
    auto t0=chrono::steady_clock::now();
    // auction: maximize -cost, i.e. benefit b_ij = -M_ij
    vector<double> price(n, 0.0);
    vector<int> owner(n, -1);      // target j -> source
    vector<int> assign(n, -1);     // source -> target
    double eps = Cmax/4.0;
    int iter_total=0;
    while(eps > 1e-12){
        // reset assignment for this scale? Bertsekas keeps prices, resets assignment
        fill(owner.begin(), owner.end(), -1);
        fill(assign.begin(), assign.end(), -1);
        int unassigned=n;
        vector<int> free_list(n); iota(free_list.begin(), free_list.end(), 0);
        while(unassigned>0){
            int i=free_list[--unassigned];
            // find best and second best target
            double best=-1e300, second=-1e300; int bj=-1;
            const double* row=&M[(int64_t)i*n];
            for(int j=0;j<n;++j){
                double val = -row[j] - price[j];
                if(val>best){ second=best; best=val; bj=j; }
                else if(val>second){ second=val; }
            }
            double bid = price[bj] + (best-second) + eps;
            price[bj]=bid;
            int prev=owner[bj];
            owner[bj]=i; assign[i]=bj;
            if(prev!=-1){ assign[prev]=-1; free_list[unassigned++]=prev; }
            iter_total++;
            if(iter_total>n*2000){ fprintf(stderr,"too many iters\n"); goto done; }
        }
        eps*=0.25;
    }
    done:;
    double ms=chrono::duration<double,milli>(chrono::steady_clock::now()-t0).count();
    double cost=0;
    for(int i=0;i<n;i++) if(assign[i]>=0) cost += M[(int64_t)i*n+assign[i]];
    cost/=n;
    printf("n=%d iters=%d time=%.1f ms cost=%.6f\n", n, iter_total, ms, cost);
}
