#include <cstdio>
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <chrono>
#include <random>
#include <cstring>
using namespace std;

// Solve assignment (uniform marginals) by eps-scaled auction.
// Writes the transport plan (1/n on the assigned permutation) into G.
int auction_solve(int n, const double* M, double* G){
    vector<double> price(n, 0.0);
    vector<int> owner(n, -1), assign(n, -1);
    vector<int> freelist(n);
    double Cmax=0;
    for(int64_t k=0, nm=(int64_t)n*n; k<nm; ++k) if(M[k]>Cmax) Cmax=M[k];
    double eps = Cmax/2.0;
    const double eps_min = 1e-11;
    int total=0;
    while(eps > eps_min){
        memset(owner.data(), 0xFF, sizeof(int)*n); // careful: owner is int, 0xFF -> -1 only if sizeof int==4 and all bytes FF. yes -1.
        // actually memset 0xFF sets -1 for two's complement. good.
        for(int i=0;i<n;++i) assign[i]=-1;
        int nfree=n;
        for(int i=0;i<n;++i) freelist[i]=i;
        int guard=0, guardmax=n*40+1000;
        while(nfree>0){
            int i = freelist[--nfree];
            const double* row = M + (int64_t)i*n;
            double best=-1e300, second=-1e300; int bj=0;
            for(int j=0;j<n;++j){
                double val = -row[j] - price[j];
                if(val>best){ second=best; best=val; bj=j; }
                else if(val>second){ second=val; }
            }
            price[bj] = price[bj] + (best - second) + eps;
            int prev = owner[bj];
            owner[bj]=i; assign[i]=bj;
            if(prev!=-1){ assign[prev]=-1; freelist[nfree++]=prev; }
            if(++guard>guardmax) break;
            total++;
        }
        eps *= 0.25;
    }
    double inv=1.0/n;
    memset(G, 0, sizeof(double)*(size_t)n*n);
    for(int i=0;i<n;++i){ int j=assign[i]; if(j>=0) G[(int64_t)i*n+j]=inv; }
    return total;
}

int main(int argc, char** argv){
    int n=argc>1?atoi(argv[1]):600;
    int seed=argc>2?atoi(argv[2]):1;
