int auction_knn(int n, const double* M, double* G, int K){
    // candidate lists: K nearest targets per source, K nearest sources per target
    vector<int> crow((size_t)n*K), ccol((size_t)n*K);
    vector<int> idx(n);
    for(int i=0;i<n;++i){
