            double best=-1e300, second=-1e300; int bj=0;
            const int* cr=&crow[(size_t)i*K];
            for(int t=0;t<K;++t){ int j=cr[t]; double val=-row[j]-price[j];
                if(val>best){ second=best; best=val; bj=j; } else if(val>second) second=val; }
            price[bj]=price[bj]+(best-second)+eps;
            int prev=owner[bj]; owner[bj]=i; assign[i]=bj;
