#include <cstdio>
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <chrono>
#include <random>
#include <cstring>
#include <numeric>
using namespace std;

// K-nearest candidate auction. Returns number of assigned sources.
int auction_k(int n, const double* M, double* G, int K){
    vector<int> cand((size_t)n*K);
    vector<int> idx(n);
    for(int i=0;i<n;++i){
        iota(idx.begin(), idx.end(), 0);
        const double* row=M+(int64_t)i*n;
        nth_element(idx.begin(), idx.begin()+K-1, idx.end(), [&](int a,int b){return row[a]<row[b];});
        // sort the K for slightly better cache; not required
        memcpy(&cand[(size_t)i*K], idx.data(), sizeof(int)*K);
    }
    vector<double> price(n, 0.0);
    vector<int> owner(n, -1), assign(n, -1), freelist(n);
    double Cmax=0; for(int64_t k=0;k<(int64_t)n*n;++k) if(M[k]>Cmax) Cmax=M[k];
    double eps=Cmax/2.0;
    const double eps_min=1e-11;
    while(eps>eps_min){
        memset(owner.data(), 0xFF, sizeof(int)*n);
        for(int i=0;i<n;++i) assign[i]=-1;
        int nfree=n; for(int i=0;i<n;++i) freelist[i]=i;
        int guard=0, guardmax=n*100+1000;
        while(nfree>0 && guard<guardmax){
            int i=freelist[--nfree];
            const double* row=M+(int64_t)i*n;
            const int* cr=&cand[(size_t)i*K];
            double best=-1e300, second=-1e300; int bj=cr[0];
            for(int t=0;t<K;++t){
                int j=cr[t];
                double val=-row[j]-price[j];
                if(val>best){ second=best; best=val; bj=j; }
                else if(val>second) second=val;
            }
            price[bj]=price[bj]+(best-second)+eps;
            int prev=owner[bj];
            owner[bj]=i; assign[i]=bj;
            if(prev!=-1){ assign[prev]=-1; freelist[nfree++]=prev; }
            guard++;
        }
        eps*=0.25;
    }
    int assigned=0;
    double inv=1.0/n;
    memset(G,0,sizeof(double)*(size_t)n*n);
    for(int i=0;i<n;++i){ int j=assign[i]; if(j>=0){ G[(int64_t)i*n+j]=inv; assigned++; } }
    return assigned;
}

int main(int argc, char** argv){
    int n=argc>1?atoi(argv[1]):600;
    int seed=argc>2?atoi(argv[2]):1;
    int K=argc>3?atoi(argv[3]):48;
    mt19937 rng(seed);
    uniform_real_distribution<double> U(0,1);
    vector<double> sp(2*n), tp(2*n);
    for(auto& x:sp) x=U(rng); for(auto& x:tp) x=U(rng);
    vector<double> M((int64_t)n*n), G((int64_t)n*n);
    for(int i=0;i<n;i++) for(int j=0;j<n;j++){
        double dx=sp[2*i]-tp[2*j], dy=sp[2*i+1]-tp[2*j+1];
        M[(int64_t)i*n+j]=sqrt(dx*dx+dy*dy);
    }
    auto t0=chrono::steady_clock::now();
    int asg=auction_k(n, M.data(), G.data(), K);
    double ms=chrono::duration<double,milli>(chrono::steady_clock::now()-t0).count();
    double cost=0; for(int64_t k=0;k<(int64_t)n*n;++k) cost+=G[k]*M[k];
    FILE* f=fopen("assign.bin","wb"); fwrite(G.data(),8,(size_t)n*n,f); fclose(f);
    FILE* fm=fopen("M.bin","wb"); fwrite(M.data(),8,(size_t)n*n,fm); fclose(fm);
    printf("n=%d K=%d assigned=%d time=%.2f ms cost=%.6f\n", n, K, asg, ms, cost);
